type DeviceEventKey = 'setWarning' | 'setAvailable' | 'setUnavailable' | 'setSettings' | 'addCapability' | 'getCapabilities' | 'getState' | 'removeCapability' | 'setClass' | 'setEnergy' | 'setCapabilityOptions' | 'getCapabilitiesOptions' | 'updateCapabilityValue' | 'setStore' | 'setImage' | 'setVideo' | 'setLastSeenAt';
